const detail = (title, body) => `<details class="chapter-details"><summary>${title}<span>+</span></summary><div>${body}</div></details>`;
const list = items => `<ul class="plain-list">${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const note = (label,text) => `<div class="editorial-note"><strong>${label}</strong><p>${text}</p></div>`;
const demo = (id,label='現有 MathConcept 示範系統') => `<div class="demo-wrap"><div class="demo-caption"><span>${label}</span><span>${id==='rollout'?'建議交付次序':'互動示範'}</span></div><div class="demo" data-demo="${id}" id="demo-${id}"></div></div>`;
const proposedFlow = (label,steps,text) => `<div class="proposed-flow"><span class="field-label">${label}</span><ol>${steps.map(step=>`<li>${step}</li>`).join('')}</ol><p>${text}</p></div>`;
export const chapters = [
 {id:'vision',title:'方案概覽'},
 {id:'system',title:'一套互相連繫的系統',kicker:'銜接教學與營運',heading:'從總部的課程規劃<br>連繫到學生的下一堂。',intro:'總部、中心、老師、家長及學生各有合適的工作空間，讓教材、課堂、習作及繳費安排互相銜接，減少重複跟進。',body:demo('system')+detail('各個角色如何配合',list(['總部編製及審批課程，決定各中心可使用的教材，並訂定營運政策。','中心職員處理報名、課堂安排、家長要求及收費事宜，清楚掌握尚待跟進的工作。','老師從所教班別選取學生、派發合適的工作紙，並檢視習作及學習進度。','學生在自己的學習資料夾完成及重溫習作；家長透過獨立介面處理課堂及繳費安排。','各方使用同一份已確認的課堂及習作紀錄。已派發習作保留當時的教材版本，答案只供獲授權人士取用。']))+note('同一套系統，各司其職','本頁可試用現有的行政、老師、家長及學生流程。總部教材發布、課程使用權及正式營運所需的配合功能，屬於建議新增範圍。')},
 {id:'protection',title:'保護課程教材',kicker:'按需要取用，按權限發放',heading:'妥善保管原檔。<br>讓教學取用更方便。',intro:'總部掌握教材原檔及發放權，中心和老師按教學需要取用已審批內容。閱覽及列印均有清楚的授權範圍和紀錄。',body:proposedFlow('建議的教材使用流程',['總部保管原檔','審批可用教材','授權閱覽或列印','查閱發放紀錄'],'中心可取得教學所需的教材；總部可掌握教材的使用及發放情況。受控列印及副本追溯仍屬建議功能。')+`<div class="three-columns"><article><h3>按角色取用</h3><p>總部管理原檔及課程使用權；中心使用獲授權教材；學生只查看已開放的習作。</p></article><article><h3>列印須經授權</h3><p>在議定的列印安排下取得已審批教材，並按中心政策管理用量及保留紀錄。</p></article><article><h3>協助追查副本來源</h3><p>可核對副本所屬的教材版本及發放紀錄，協助總部了解有關中心、帳戶及列印情況。</p></article></div>`+detail('保障範圍與實際限制',list(['教材原檔由總部保管。日常教學只提供獲授權的內容，老師及學生的取用範圍清楚分開。','列印安排須訂明誰可列印、可用教材、用量及異常工作的跟進責任，讓職員知道列印是否完成。','副本追溯效果須在議定的掃描、拍攝及影印條件下驗證，再確定可承諾的識別能力。','可閱覽或列印的內容仍可能被截圖、拍攝或再次複製。這些保障可減少隨意大量取用及協助調查，但不能保證杜絕所有外洩。','副本識別結果可協助查找發放紀錄，不能單憑該結果證明是哪一位人士洩漏。','中心或帳戶停用後，須終止其後的取用權；已拍攝或列印的內容則無法收回。']))},
 {id:'library',title:'沿用現有教材庫',kicker:'保留累積的教學價值',heading:'讓逾 200,000 份檔案<br>更容易找到和使用。',intro:'先讓現有教材可搜尋、可派發及可用於數碼習作，再按課程優先次序，逐步增加可重用及可編輯的題目。',body:demo('library','課程目錄及習作派發')+note('現有教材目錄','示範採用已提供的課程索引。小三及小六設有示例題目；工作紙原檔的加入及可編輯內容的轉換，仍屬待完成的工作。')+`<div class="three-columns numbered"><article><span>01</span><h3>沿用原有頁面</h3><p>保留熟悉的教材版面，讓老師更容易搜尋、派發，學生可在頁面上書寫。</p></article><article><span>02</span><h3>重用現有題目</h3><p>將已核實的題目及附圖用於不同工作紙，減少重複編製。</p></article><article><span>03</span><h3>逐步增加可編輯題目</h3><p>優先整理常用教材，核對文字、算式及答案後，讓編製人員更容易修改和延伸。</p></article></div>`+detail('教材整理成果及品質要求',list(['以實際教材盤點確認涵蓋範圍及工作量，包括檔案格式、頁數、完整程度及現有分類。檔案數目不等於題目數目。','保留原有教材及修訂關係，清楚區分重複內容與不同版本，讓編製人員知道應使用哪一份。','老師可按年級、課題及教材系列，從學習進度表找到正確的已審批工作紙。','可搜尋的內容未必已達到可編輯教材的品質。轉換結果完成核對前，仍以忠於原檔的頁面供教學使用。','核對小數點、分數、單位、附圖、分題及答案對應關係。未能可靠轉換的題目，先保留原有呈現方式。','交付成果分別列明可取用教材的涵蓋程度，以及已核實可編輯題目的數量；兩者的範圍及驗收要求須分開議定。']))},
 {id:'authoring',title:'編製新教材',kicker:'支援備課與課程發展',heading:'為數學教學而設的<br>工作紙編製工具。',intro:'組合已審批題目、編寫新題目，並預留足夠思考及運算空間。同一份工作紙可供直向平板使用，亦可列印為清晰的 A4 教材。',body:proposedFlow('建議的教材編製流程',['編寫或選取題目','審閱答案及版面','發布供老師派發'],'編製人員可重用現有題目、加入新內容，並在發布前確認教學品質。工作紙編製及 AI 輔助功能尚未納入現有示範。')+`<div class="two-columns"><article><h3>更容易編製和重用</h3><p>集中管理題目、算式、附圖、答案及評分指引，按課程需要組成工作紙，減少重複整理。</p></article><article><h3>AI 輔助，編審把關</h3><p>AI 可協助尋找例題、草擬變化題及整理內容。編製人員負責確認題意、答案、難度及版面，並決定是否發布。</p></article></div>`+detail('教材編製及審閱要求',list(['優先支援日常工作紙所需的文字、算式、圖片、可重用題目、答案欄及手寫空間；專門的互動圖形按課程需要另行議定。','AI 產生的內容均屬草稿。題目是否清楚、答案是否正確、難度是否合適，以及解題方法是否符合教學要求，都須經審閱。','任何外部內容處理，均須事先議定教材使用權、資料保密要求及批准責任。本建議書並不授權將教材交予外部 AI 或其他內容處理服務。','學生可取用的習作、搜尋結果及匯出內容，不應包含受限制答案或老師備註。','發布前可檢視平板及 A4 版面，確認分頁、運算空間及題目完整性，避免同一道題目的內容難以對照。','已派發習作保留原有版本。教材修訂供之後派發使用，讓老師能按學生實際完成的題目批改及跟進。']))},
 {id:'teacher',title:'老師教學工作台',kicker:'縮短備課與派發流程',heading:'讓學習進度表<br>成為日常教學工作台。',intro:'老師從班別及學生出發，找到合適的工作紙、派發習作並跟進進度。教材先按學生年級呈現，亦可按教學需要瀏覽其他級別。',body:demo('teacher')+note('相連的操作示例','選好工作紙後，按「Send to student」（發送給學生），再按「View student app」（查看學生應用程式），即可開啟該學生的學習資料夾。「Prepare for later」（留待之後使用）會保留習作，直至老師開放才供學生使用。')+detail('日常教學可完成的工作',list(['按實際授課時段找到班別及學生，減少在不同名單之間來回查找。','從學習進度表按年級、課題及教材系列選取工作紙，清楚知道正在使用的教材。','分別掌握已派發習作、學生進度、待批改習作及改正；獲授權職員亦可查看相關內容。','將已審批工作紙派作課堂習作或家課，亦可先預備日後習作，再按教學進度開放。','在原有題目旁查看學生的手寫運算、批改及改正紀錄，保留完整的學習脈絡。']))},
 {id:'student',title:'學生學習空間',kicker:'熟悉的資料夾，方便專心學習',heading:'更多空間寫出解題過程。<br>更容易掌握要做的習作。',intro:'以三個熟悉分類整理習作：現在要做、已完成，以及老師預備日後使用的習作。以直向平板及書寫體驗為重點，讓學生專心解題。',body:demo('student')+detail('學生體驗及試行要求',list(['目前習作包括上一堂的改正；已完成習作仍可重溫，方便學生查看自己的解題過程。','日後習作在老師開放前不能取用，讓學生按教學進度學習。','操作按鈕保持精簡，並提供全螢幕書寫空間。家長及學生介面使用香港繁體中文。','學生重新開啟習作時，已儲存的筆跡應完整保留，並出現在正確的題目及位置。','試行須確認議定裝置上的觸控筆書寫、手掌接觸畫面時的使用體驗，以及中斷後繼續習作的情況。是否支援離線使用及其範圍，須另行議定。','自動批改只適用於已驗證的題型。涉及手寫推理及解題方法的給分，仍須支援老師審閱及判斷。']))},
 {id:'operations',title:'中心與家長協調',kicker:'讓課堂安排清晰明確',heading:'職員可依據的時間表。<br>家長清楚知道下一步。',intro:'家長請假後，中心即有待跟進紀錄，再由職員與家長確認補堂。臨時及永久調堂均先顯示對課堂數目的影響，讓雙方按清楚的安排作決定。',body:demo('operations')+`<div class="two-columns"><article><h3>家長提出請假</h3><p>請假獲確認後，家長可提供補堂日期偏好，並清楚知道客服會聯絡完成安排。</p></article><article><h3>職員確認補堂</h3><p>原有課堂以刪除線標示，並列入請假區。待職員確認雙方同意的時間後，才正式排入補堂。</p></article></div>`+detail('課堂安排及跟進要求',list(['職員可將課堂拖放至新時段或請假區，亦可用鍵盤完成相同操作，並清楚看到更改結果。','容易辨認老師未能授課的時段。確認調堂前，先掌握名額、可用時間及時間衝突。','調堂可設定生效日期及結束日期；臨時安排結束後，恢復原有恆常上課時間。','清楚比較更改前後的課堂數目。增加課堂時須決定額外課堂的處理方式；減少課堂時須決定是否保留補堂額度。','課堂及收據修訂保留原有紀錄和更改原因，方便職員查核。最終文件的修訂及日期政策仍須議定。','學生資料包括餘下課堂日期；家長溝通及課堂備註保留在相關學生及課堂之下，方便接手跟進。']))},
 {id:'billing',title:'繳費及最終對帳',kicker:'清楚顯示下一步要做甚麼',heading:'掌握待處理事項。<br>以銀行紀錄完成核對。',intro:'逐張帳單追蹤家長付款、中心審核及收據發出進度，再於獨立的最終對帳流程中，將已發出的收據與銀行紀錄核對。',body:demo('billing')+note('收據發出與銀行對帳各有狀態','建議的「Auto-sent」（自動發送）政策，會在付款證明通過議定檢查後發出收據，但不代表已確認銀行入帳。中心亦可採用人手審核，再於最終對帳找出須跟進的差異。')+detail('收費工作及例外情況',list(['每張帳單各自顯示進度。同一名學生可同時有較早期的未繳帳單、待審核帳單及已完成帳單。','職員先看到中心待審核事項、繳費限期及逾期帳單。付款證明由最舊開始處理，收據則由最新開始查看。','可按學生或帳單搜尋，並按收費類別及收費月份篩選。月份可留空，讓較早期的未繳帳單仍在清單中；每頁約 25 張帳單，方便分批處理。','並排核對帳單及付款證明，確認後發出收據。退回證明時須說明原因，讓家長知道需要補交證明，而非再次付款。','審核未能儲存時，應保留已填內容及清楚提示跟進。提醒有發送紀錄，避免 24 小時內重複通知；已取消及已作廢帳單可供查閱。','建議中心預設採用「Auto-sent」（自動發送）。付款證明未通過檢查或結果不確定時，交由職員審核。現有示範的付款檢查屬模擬功能，正式使用前仍須驗證。','銀行對帳應避免重複計入交易或重複分配同一筆入帳，並列出遺漏、多出及配對不明確的紀錄。付款發起、證明提交、收據發出及銀行入帳日期須清楚區分。','現金、支票、合併付款、部分付款及退款，須各自議定處理規則。基本方案以銀行月結單完成對帳；待銀行確認的直接銀行連接屬可選範圍。']))},
 {id:'franchise',title:'跨中心營運',kicker:'以一致管理支援擴展',heading:'總部訂定標準。<br>中心處理日常營運。',intro:'各中心取得所需的課程教材及營運工具，總部統一管理教材發布及使用政策。權限和責任清楚分工，支援更多中心沿用一致流程。',body:demo('franchise','荃灣及坑口')+note('兩間中心的示範','荃灣及坑口沿用同一套工作流程，並各自保留中心資料、老師及示範紀錄。總部權限管理及跨中心報表屬建議新增功能。')+detail('總部與中心的管理成果',list(['各中心只可取用獲授權的課程及營運資料，不能因切換中心畫面而取得其他中心的受限制紀錄。','總部決定教材發布、版本及課程使用權；中心按議定的角色權限處理教學及日常營運。','異常取用或列印量可交由指定人員查核。紀錄用作跟進依據，不應自動視為違規證明。','中心掌握尚待完成的課堂及繳費事項；總部可按雙方議定的報表定義了解跨中心營運情況。','新中心啟用、職員變動及加盟合作結束時，均須有清楚的權限、支援及交接安排，並確認所需語言。','MathConcept 保留所提供課程教材及營運資料的擁有權。軟件擁有權、授權、資料匯出及交接安排須在協議中訂明。']))},
 {id:'rollout',title:'遷移、試行及推展',kicker:'以可核對的成果決定下一步',heading:'從一間中心開始。<br>以實際成果支持推展。',intro:'先以真實教材、議定裝置及職員日常流程完成試行。每個階段均有清楚的驗收成果，由雙方確認後再決定下一步。',body:demo('rollout','交付路線圖')+`<div class="two-columns responsibility"><article><h3>MathConcept 提供</h3><p>獲授權教材及原始資料、課程及營運負責人、具代表性的例外情況、試行用戶，以及適時的審閱決定。</p></article><article><h3>交付團隊提供</h3><p>議定的設計及開發、教材及資料遷移成果、驗證報告、職員培訓、文件及推出支援。</p></article></div>`+detail('可共同驗收的試行成果',list(['老師能找到正確的已審批工作紙、派發予學生，並在議定裝置上檢視學生已儲存的習作。','學生遇到議定的中斷情況後，能繼續已儲存的習作，筆跡完整保留且位置正確。','家長請假後，原有課堂及職員待辦清單會更新；補堂時間仍待職員與家長確認。','帳單按議定的人手或自動收據政策處理。與銀行月結單核對後，未能解釋的差異及重複分配均可被識別和跟進。','未獲授權的中心不能取得原檔、其他中心的學生紀錄或受限制答案；停用帳戶不能繼續取用教材。','職員能確認已審批列印工作的完成或失敗狀態，並查閱相關紀錄。副本追溯效果按議定的拍攝、掃描及影印條件驗收。','遷移樣本保留所需算式、附圖及版面；未達要求的項目清楚列入報告，經修正或同意後保留原有呈現方式。','按議定的日常使用及中斷情況，確認中心能持續處理核心工作，並清楚知道復原結果及尚待跟進事項。']))},
 {id:'proposal',title:'範圍、投資及下一步',kicker:'建立清晰的交付基礎',heading:'議定首階段版本。<br>讓下一個決定更具體。',intro:'本初稿以可操作的流程說明建議方向。待教材庫、營運規則及試行要求完成驗證後，再落實交付範圍、價格及日期。',body:`<div class="scope-matrix"><article><span class="scope-label">基礎功能</span><h3>建議首階段版本</h3><p>按議定試行範圍，提供受控教材庫、老師派發習作、學生學習資料夾、中心及家長流程、帳單待辦清單，以及銀行月結單對帳。</p></article><article><span class="scope-label">分階段發展</span><h3>教材編製及中心擴展</h3><p>工作紙編製、經核實的可編輯題目、指定 AI 輔助功能、更完整的報表，以及按計劃推展至更多中心。</p></article><article><span class="scope-label">先驗證可行性</span><h3>確認成果後再作承諾</h3><p>大量教材轉換的品質、列印安排、手寫體驗、副本追溯能力、待銀行確認的直接銀行連接，以及其他付款方式。</p></article></div><div class="commercial-panel"><div><span class="eyebrow">商業安排基礎</span><h3>清楚區分各部分投資。</h3></div><div class="cost-lines"><div><span>平台設計及開發</span><strong>待界定範圍</strong></div><div><span>教材庫遷移及可編輯內容轉換</span><strong>另行報價</strong></div><div><span>日常營運及服務費用</span><strong>須議定用量及服務範圍</strong></div><div><span>支援、維護及培訓</span><strong>待議定服務條款</strong></div></div></div><div class="decision-box"><span>下一個決定</span><h3>議定具代表性的試行方案及成功指標。</h3><p>確認參與中心、教材樣本、所需裝置及列印安排、決策負責人，以及優先處理的流程，再形成具體的交付計劃及商業建議書。</p><div class="button-row"><button class="primary-button" data-action="reference" data-ref="scope">閱讀詳細範圍 <span>↗</span></button><button class="secondary-button" data-action="reference" data-ref="assumptions">查看待決定事項</button></div></div>`+detail('擁有權、支援及交接',list(['MathConcept 保留其提供的課程教材及營運資料擁有權。新軟件及新內容的擁有權與授權安排須於協議中訂明。','議定日常營運責任、資料保管及復原要求、獲授權的資料匯出，以及更換服務或合作結束時的交接安排。','訂明支援時間、事故跟進、更新及安全維護責任，讓中心清楚知道遇到問題時由誰處理。','費用及時間表以經驗證並議定的範圍為依據。本初稿不構成任何開發價格或交付日期的承諾。']))}
];
export function chapterHTML(c,i){return `<section class="chapter" id="${c.id}" data-chapter="${i}" aria-labelledby="heading-${c.id}"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${c.kicker}</div><div class="chapter-heading"><h2 id="heading-${c.id}">${c.heading}</h2><p class="section-intro">${c.intro}</p></div>${c.body}</section>`}
export const references = {
 scope:{title:'詳細範圍',body:`<p class="reference-lead">以下為供討論的交付範圍。建議功能須經驗證及雙方議定，並不表示現有示範已具備正式營運能力。</p><h3>課程及教材</h3>${list(['總部保管原檔及管理教材目錄，按年級、課題及教材系列搜尋，並保留清楚的版本紀錄和使用權限。','先讓現有教材可用於教學，再逐步增加可重用題目及經核實的可編輯內容。','編製包含算式、附圖及運算空間的工作紙，預覽平板及 A4 版面，經審閱後發布。','AI 協助尋找例題、草擬及整理內容；教材使用及外部處理須獲批准，發布決定由人手負責。'])}<h3>教與學</h3>${list(['按老師授課時段找到班別及學生，按年級及教學需要選取教材，並透過學習進度表派發。','提供課堂習作及家課，以及目前、已完成和日後習作資料夾，支援手寫運算、批改及改正。','日後習作由老師決定何時開放；已派發習作保留原有版本，方便按實際內容跟進學習。','議定支援裝置、習作儲存及中斷後繼續使用的驗收要求；離線使用另行確認。'])}<h3>中心及家長事務</h3>${list(['清楚顯示課堂安排、老師可授課時間、課堂備註、餘下課堂及學生資料。','家長可請假及提供補堂日期偏好，職員從待辦事項跟進並確認補堂。','支援單次、臨時及恆常調堂，在確認前掌握時間衝突及課堂數目變化。','家長可見紀錄及溝通內容保留在相關學生及課堂之下，方便雙方查閱。'])}<h3>收費</h3>${list(['逐張帳單掌握待辦事項，提供人手審核、可選的「Auto-sent」（自動發送）政策、提醒及可查閱的收據紀錄。','按學生及帳單搜尋，並按收費類別及月份篩選。月份可留空，保留較早期未繳帳單；每頁約 25 張帳單，方便處理大量紀錄。','以銀行月結單完成最終對帳，協助配對及分配入帳，識別重複、遺漏及需跟進的差異。','現金、支票、退款及合併或部分付款的規則須另行議定；待銀行確認的直接銀行連接須獨立評估。'])}<h3>總部及加盟中心</h3>${list(['清楚劃分中心資料、課程使用權及角色責任，支援教材審批及停用後撤銷取用權。','提供取用及列印紀錄、營運概況、遷移成果報告、培訓及議定的支援安排。'])}<h3>示範範圍及限制</h3><p>內嵌畫面採用現有 MathConcept 示範系統。示範紀錄不會跨裝置同步。荃灣時間表的姓名及時段來自已提供的時間表；繳費及其他流程紀錄則為示例。小三及小六設有示例題目，其他目錄項目尚待加入工作紙原檔。付款檢查屬模擬功能。總部教材發布、內容轉換、工作紙編製、受控列印及正式營運所需的取用保障，仍屬建議範圍。</p>`},
 safeguards:{title:'教材與營運保障',body:`<p class="reference-lead">以下列出建議方案應達到的保障成果。具體範圍、驗收條件及雙方責任，須在試行及正式服務安排中議定。</p><h3>按權限取用教材及資料</h3>${list(['總部掌握教材原檔、發布決定及課程使用權；中心和老師只取用獲授權內容。','學生只可開啟已獲派發並已開放的習作，不能取得受限制答案、老師備註或原檔。','各中心的學生及營運資料有清楚的取用界線。職員離任、帳戶停用或合作結束後，應終止其後的取用權。'])}<h3>有紀錄的授權列印</h3>${list(['獲授權人士可按中心政策列印已審批教材，並清楚知道工作已完成、失敗或需要跟進。','總部及指定職員可查閱列印紀錄及用量，按議定程序跟進異常情況。','列印安排、可支援的打印機、責任分工及驗收結果，須在試行中確認。'])}<h3>可追溯，並清楚交代限制</h3>${list(['副本追溯可協助查找教材版本及發放紀錄，為調查提供線索。其效果須按議定的掃描、拍攝及影印條件驗證。','副本識別結果不能單獨證明洩漏者身分，任何跟進均須結合其他資料及既定程序。','閱覽、列印及追溯措施不能保證完全杜絕截圖、拍攝、複製或外洩；已發出的紙本及影像亦無法收回。'])}<h3>日常運作及中斷後復原</h3>${list(['在議定的日常使用情況下，老師可派發教材、學生可完成習作，職員可處理課堂及繳費工作。','工作未能完成時，使用者應清楚知道結果及下一步，避免重複發出收據、重複計入款項或遺失已儲存內容。','試行須確認議定中斷情況下的復原結果，包括可恢復的資料、預期恢復時間、通知及跟進責任。','教材整理後仍須保留數學內容及版面的教學價值；未能確定的轉換結果須交由指定人員審閱。'])}<h3>擁有權及持續使用</h3>${list(['MathConcept 保留其提供的課程教材及營運資料擁有權，並可按議定權限及範圍取得所需資料。','新軟件及新內容的擁有權、使用授權、資料匯出及交接責任，須在協議中訂明。','任何外部內容處理均須符合已批准的教材使用及保密要求；本提案不代表已取得有關授權。','支援、維護、事故跟進及合作結束時的安排須清楚列明，讓中心可規劃持續營運。'])}`},
 assumptions:{title:'待決定事項及責任分工',body:`<p class="reference-lead">以下決定會影響交付範圍、費用及時間表，可於需求確認及試行階段逐項落實。</p><h3>教材</h3>${list(['現有教材的格式、頁數及完整程度，以及應以哪個版本作為準則。','優先整理的年級及工作紙系列，以及首階段需要多少經核實的可編輯題目。','負責核對數學內容、答案、版面及批准發布的人員。','是否允許外部內容處理，包括 AI 輔助，以及所需的教材使用權及保密要求。'])}<h3>教學及裝置</h3>${list(['課堂須支援的平板、觸控筆及列印安排，以及代表實際使用情況的試行裝置。','是否需要離線做習作，以及可使用的教材範圍和重新連線後應有的結果。','需要自動批改、互動圖形或人手審閱的題型，以及可接受的品質要求。'])}<h3>營運及財務</h3>${list(['請假、補堂有效期、調堂及額外課堂的處理規則。','收據措辭、「Auto-sent」（自動發送）所需的付款證明，以及與銀行對帳分開顯示的狀態。','可提供的銀行紀錄、配對及款項分配規則，以及現金、支票、部分付款、退款及月結差異的處理方式。','通知渠道、訊息保留安排，以及與家長溝通和跟進的責任分工。'])}<h3>商業安排及推展</h3>${list(['試行中心、參與用戶、具代表性的教材樣本，以及負責驗收的決策人員。','可量度的成功指標，以及推展至整間中心或海外前所需的確認。','原始資料整理、軟件及內容擁有權、使用授權、日常營運、支援和交接責任。','完成範圍及假設驗證後，確認價格、實施時間表，以及日常營運及服務費用。'])}`}
};
